struct Reader{std::vector<std::uint8_t> bytes;std::size_t at=0;std::uint32_t word(){auto v=warrior_curve_word(bytes,at);at+=4;return v;}float value(){return std::bit_cast<float>(word());}std::vector<std::uint8_t> take(std::size_t n){warrior_curve_require(at<=bytes.size()&&n<=bytes.size()-at,"Matrix fixture truncated");std::vector<std::uint8_t> r(bytes.begin()+std::ptrdiff_t(at),bytes.begin()+std::ptrdiff_t(at+n));at+=n;return r;}std::string name(){auto n=word();warrior_curve_require(n>0&&n<=96,"Matrix fixture name");auto b=take(n);return std::string(b.begin(),b.end());}};
