 warrior_curve_require(argc==3,"Usage: native_bone_matrices MATRIX_FIXTURE CURVE_FIXTURE");auto r=load(argv[1]);auto magic=r.take(8);warrior_curve_require(std::string(magic.begin(),magic.end())=="BNWBMAT1"&&r.word()==33,"Actual matrix fixture schema");auto ids=r.take(64);constexpr char digits[]="0123456789abcdef";std::string hex;for(auto b:ids){hex+=digits[b>>4];hex+=digits[b&15];}warrior_curve_require(hex=="7c9f93d512c49a7ab2bc70f51c6caa10a82ddd697ac11d8a24ff1bb7ce7c36867eed0924e1559e030c8d4f14746d1ad93c4f3e87550789a96fc80f8feb713d7e","Foreign source matrix identities");
